import{_ as e,o as t,c as r,a3 as i}from"./chunks/framework.Dj4Lt7vj.js";const _=JSON.parse('{"title":"通知设置","description":"","frontmatter":{"title":"通知设置"},"headers":[],"relativePath":"client/notify.md","filePath":"client/notify.md","lastUpdated":1787949005000}'),o={name:"client/notify.md"};function l(n,a,p,s,c,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="通知设置" tabindex="-1">通知设置 <a class="header-anchor" href="#通知设置" aria-label="Permalink to &quot;通知设置&quot;">​</a></h1><p>熠智 AI 会在客户端和网页工作台显示业务提醒。绑定微信后，部分提醒也可以通过微信服务号推送。</p><p>入口：客户端左下角「设置」→「通知」。</p><h2 id="客户端通知" tabindex="-1">客户端通知 <a class="header-anchor" href="#客户端通知" aria-label="Permalink to &quot;客户端通知&quot;">​</a></h2><p>接待异常和需要处理的事项会出现在客户端通知或异常列表里。看到转人工失败、客服离线等提醒时，请及时打开对应店铺检查。</p><h2 id="微信通知" tabindex="-1">微信通知 <a class="header-anchor" href="#微信通知" aria-label="Permalink to &quot;微信通知&quot;">​</a></h2><p>绑定微信后，重要消息会通过微信服务号的模板消息推送。</p><p>绑定步骤：</p><ol><li>在「设置 → 通知」里点「绑定微信」。</li><li>用微信扫描弹出的二维码。二维码有效期 5 分钟，过期关闭弹窗重新获取。</li><li>扫码成功后页面会提示绑定完成。</li></ol><p>绑定后可以随时解绑，或临时关闭「接收微信通知」而保留绑定关系。</p><p>网页工作台的「通知」标签页里也有同样的微信绑定入口。</p><h2 id="关于短信" tabindex="-1">关于短信 <a class="header-anchor" href="#关于短信" aria-label="Permalink to &quot;关于短信&quot;">​</a></h2><p>短信不是商家可以自由选择事件的通知渠道。平台只会在部分服务告警场景自动发送短信，是否发送由平台规则决定，部分场景还会受短信额度影响。日常请以客户端通知、网页工作台通知和已绑定的微信通知为准。</p><p>经营闲鱼店铺时请特别留意客户端和聊天记录里的待跟进会话，因为闲鱼不支持转人工。</p><h2 id="查看历史通知" tabindex="-1">查看历史通知 <a class="header-anchor" href="#查看历史通知" aria-label="Permalink to &quot;查看历史通知&quot;">​</a></h2><p>网页工作台的「通知」标签页保存了通知列表，可以按分类查看和删除，见<a href="/aicare-docs/workspace/overview">工作台总览</a>。</p>',16)])])}const f=e(o,[["render",l]]);export{_ as __pageData,f as default};
